definition.raw:
Define 
\begin{align*}
n_{\eps,+} = \{i:\; \epsilon_i > 0\}, \quad n_{\eps,-} = n - n_{\eps,+},  \quad n_{X_1,+} = \{i:\; X_{i1} > 0\}, \quad n_{X_1,-} = n - n_{X_1,+}.

\cite{CandesTao2005} Let $A \in {\mathbb R}^{N \times p}$ and $B_0(s;p) = \{v \in {\mathbb R}^p: \; \nnorm{v}_0 \leq s \}$. Define the $s$-sparse minimum and maximum eigenvalues associated with $A$ by 
\begin{equation*}
  \lambda_{\min}(s) = \min_{v \in B_0(s;p) \setminus \{0\}} \frac{\nnorm{A v}_2^2}{\nnorm{v}_2^2}, \qquad
  \lambda_{\max}(s) = \max_{v \in B_0(s;p) \setminus \{0\}} \frac{\nnorm{A v}_2^2}{\nnorm{v}_2^2}. 
\end{equation*}
Let $\delta \in (0,1)$. We say that $A$ is an ($s$, $\delta$)-\textbf{restricted isometry}  if
\begin{equation*}
  1 - \delta \leq \lambda_{\min}(s) \leq \lambda_{\max}(s) \leq 1+\delta.
\end{equation*}

\cite{Bickel2009} Let $A \in {\mathbb R}^{N \times p}$. We define the $(s, \alpha)$-\textbf{restricted eigenvalue} by 
\begin{equation}\label{eq:recondition}
\phi(s, \alpha) = \min_{J \in \mc{J}(s)} \, \min_{v \in \mc{C}(J, \alpha) \setminus
  0}\, \, \frac{\nnorm{A v}_2^2}{\nnorm{v_J}_2^2}. 
\end{equation}

theorem.raw:
\label{theo:constrained_permutation} Consider optimization problem \eqref{eq:lsq} and for positive integers $m$, 
denote $\nu_m = \E_{g \sim N(0, I_m)}[\nnorm{g}_2] \in \left[\frac{m}{(m+1)^{1/2}}, \; m^{1/2} \right]$ and let $\varepsilon \in (0,1/2)$ be a number such that 
\begin{equation}\label{eq:cond_samples_unrelaxed}
\nu_{n-d} - \frac{\epss}{1-\varepsilon}\nu_n \geq \frac{2}{1 - \varepsilon} w(\mc{T}). 
\end{equation}
If furthermore $n > 9 \vee 4d$, then with probability $\geq 1 - \frac{7}{2}\exp(-c_{\epss} n) - 2 \exp \left(-\frac{1}{2} (d \vee \log n) \right)$,  
\begin{equation}\label{eq:bound_samples_unrelaxed}
\nnorm{\wh{\beta} - \beta^*}_2 \leq   \frac{\sigma}{1 - \sqrt{\frac{4 d \vee \log n}{n}}} \left(\sqrt{\frac{5 (d \vee \log n)}{n}} + \frac{2 (1 + \sqrt{2}) \epss^{-2} \{w(\mc{T}) \vee \log n\}}{\sqrt{n}} \right).
\end{equation}

\label{theo:relaxation} Let $(\wt{\beta}, \wt{e})$ be a minimizer of \eqref{eq:relax_2} with $\lambda = 4 (1 + M) \sigma \sqrt{2 \log(n) / n}$ for some $M > 0$. There exist constants $c_1, c_2, \epss > 0$ so that if
\begin{equation*}
k \leq c_1 \frac{n-d}{\log(n/k)},
\end{equation*}
the following holds with probability $\geq 1 - 2 \exp(-c_2 (n-d)) - 2n^{-M^2} - 2 \exp \left(-\frac{1}{2} (d \vee \log n) \right)$:
\begin{equation}\label{eq:bound_samples_relaxed}
\nnorm{\wt{\beta} - \beta^*}_2 \leq \frac{\sigma}{1 - \sqrt{\frac{4 d \vee \log n}{n}}} \left(\sqrt{\frac{5 (d \vee \log n)}{n}}  +  48 (1 + M) \frac{n}{n-d} \epss^{-1} \sqrt{\frac{2k \log n}{n}}\right).  
\end{equation}

\label{theo:permutationrecovery}
  For $b \in {\mathbb R}^d$, consider $\wh{\Pi}(b) = \argmax_{\Pi \in \mc{P}_n} \scp{\Pi X b}{\y}$.  
\begin{itemize}
\item[(a)] Let $\delta, \Delta, \eta > 0$, and let $\wh{\theta}$ be an estimator s.t.~the event $\{\nnorm{X \wh{\theta} - X\beta^*}_{\infty} \leq \sigma \Delta \}$ holds with probability at least $1 - \eta$. If 
  \begin{equation*}
    \dfrac{\|\beta^*\|_2^2}{\sigma^2}>\dfrac{n^2(n-1)^2}{4 \delta^2\pi} \left( \Delta + 2 \log\dfrac{n(n-1)}{\delta} \right)^2, \: \: \text{then} \: \: \p(\widehat{\Pi}(\wh{\theta}) \ne \Pi^*)\le 2\delta + \eta.
  \end{equation*}
\item[(b)] Suppose that $n \geq 5$. If
  \begin{equation*}
    \dfrac{\|\beta^*\|_2^2}{\sigma^2}< C n^2, \: \: \text{for some constant $C>0$, then} \: \: \p(\widehat{\Pi}(\beta^*)\ne \Pi^*)\ge .35.
  \end{equation*}
\end{itemize}

lemma.raw:
\label{lem:decoupling} Consider optimization problem \eqref{eq:lsq}. Then, if $n \geq  d$, with probability one 
\begin{equation}\label{eq:decomposition}  
  \wh{\Pi}^{\T} \in \argmin_{\Pi \in \mc{P}_{n,k}} \nnorm{\pre_X^{\perp} \Pi \mathbf{y}}_2^2, \qquad \wh{\beta} \in \left\{ \left(\frac{X^{\T} X}{n} \right)^{-1} \frac{X^{\T} \wh{\Pi}^{\T} \y}{n},
  \; \, \wh{\Pi}^{\T} \in \argmin_{\Pi \in \mc{P}_{n,k}} \nnorm{\pre_X^{\perp} \Pi \mathbf{y}}_2^2 \right \}.  
\end{equation}

\label{lem:bound_pi} Under the conditions of Theorem \ref{theo:constrained_permutation}, the following holds
  with probability at least $1 - \frac{7}{2} \exp \left(-\frac{\psi(\epss, d/n) \nu_n^2}{8} \right) - \exp(-\{ w(\mc{T}) \vee \log n\})$,
  where $\psi(\epss, d/n)$ is defined in \eqref{eq:lowerbound} below. 
\begin{equation*} 
\nnorm{\wh{\Pi}^{\T} \y - \Pi^{*\T} \y}_2 \leq  \frac{2 (1 + \sqrt{2})\sigma \epss^{-2} \{w(\mc{T}) \vee \log n\}}{\sqrt{n}}.
\end{equation*}

\label{lem:Xteps} Let $\sigma_{\min}(\cdot)$ denote the minimum singular value of a matrix. If $n \geq 9 \vee 4d$, it holds that
\begin{align*}
  &\p \left( \left \{\sigma_{\min}(X / \sqrt{n}) < 1 - \sqrt{\frac{4 d \vee \log n}{n}} \right \}   \cup \left\{ \norm{ \left(\frac{X^{\T} X}{n} \right)^{-1} \frac{X^{\T} \eps}{\sqrt{n}}}_2 \geq \sigma \frac{\sqrt{5 (d \vee \log n)} \}}{1 - \sqrt{\frac{4 d \vee \log n}{n}}} \right \} \right)\\
  &\leq 2 \exp \left(-\frac{1}{2} (d \vee \log n) \right).  
\end{align*}

\label{lem:decoupling_LAD} 
Consider optimization problem \eqref{eq:relax_2} with solution $(\wt{\beta}, \wt{e})$. Then, if $n \geq d$, with probability one
\begin{align*}
  \wt{e} \in \argmin_{e} \frac{1}{n} \nnorm{\pre_X^{\perp} (\y - \sqrt{n}  e)}_2^2 + \lambda \nnorm{e}_1, \quad
  \wt{\beta} \in \Bigg\{ &\left(\frac{X^{\T} X}{n} \right)^{-1} \frac{X^{\T} (\y - \sqrt{n} \wt{e})}{n}, \\
  &\wt{e} \in \argmin_{e} \frac{1}{n} \nnorm{\pre_X^{\perp} (\y - \sqrt{n} e)}_2^2 + \lambda \nnorm{e}_1 \Big \}.
\end{align*}

\label{lem:bound_e} Under the conditions of Theorem \ref{theo:relaxation}, with probability at least $1 - 2 \exp(-c_{\epss} (n-d))  - 2n^{-M^2}$, we have 
\begin{equation*}
\nnorm{\wt{e} - e^*}_2 \leq   48 (1 + M) \sigma  \frac{n}{n-d} \epss^{-1} \sqrt{\frac{k \log n}{n}}.  
\end{equation*}

\label{lem:up}
Let $\gamma, \delta > 0$. Consider the event 
\begin{equation}\label{eq:Agamma}
\mathcal{A}_{\gamma}= \left\{\min_{i<j}(\x_i^\top\beta^*-\x_j^\top\beta^*)^2\le \gamma^2 \right\}.
\end{equation}
Then $\p\left( \mathcal{A}_{\gamma}\right)< \delta$ if 
\[
\nnorm{\beta^*}_2^2>\dfrac{n^2(n-1)^2}{4\delta^2\pi}\gamma^2.
\]

\label{lem:fixed}
Conditional on $X$, we have $\p \left(\widehat{\Pi}(\beta^*) \ne \Pi^*\mid X \right)<\delta$ if
\begin{equation}\label{eq:fix}
\min_{i<j}\left(\x_i^\top\beta^*-\x_j^\top\beta^*\right)^2>4\sigma^2\log\dfrac{n(n-1)}{\delta}.
\end{equation}

\label{lem:low}
Consider the event $\mc{A}_{\gamma}$ in \eqref{eq:Agamma}. Then, for all $n \geq 5$, $\p\left( \mathcal{A}_{\gamma}\right)\ge 0.85$ if 
\begin{equation}\label{eq:lb}
\|\beta^*\|_2^2\le \dfrac{1}{25\pi}n^2\gamma^2.
\end{equation}

\cite{Baraniuk2006}
Let $A$ be a random of matrix of size $N \times p$ satisfying 
\begin{equation}\label{eq:normpreservation}
 \p((1 - \epss) \nnorm{v}_2^2 \leq \nnorm{A v}_2^2 \leq (1 + \epss) \nnorm{v}_2^2) \leq 2 \exp(-N c_0(\epss))
\end{equation}
for any $\epss \in (0,1)$ and any $v \in {\mathbb R}^p$, where $c_0(\epss) > 0$ is a constant depending only on $\epss$. Then for any $\delta \in (0,1)$, there exist constants $c_1, c_2 > 0$ depending only on $\delta$ such that $A$ is a $(q, \delta)$-restricted isometry for any $q \leq c_1 N / \log(p/q)$ with probability at least $1 - 2 \exp(-c_2 N)$.

\label{lem:DasGupta}(from Lemma 2.2 in \cite{DasGupta2003})
  Let $\pre$ denote the orthogonal projection on an $N$-dimensional subspace of ${\mathbb R}^p$ chosen uniformly at
  random from the Grassmannian $\textsf{G}(p, N)$. Then, for any $v \in {\mathbb R}^p$ and any $\epss \in (0,1)$,
  \begin{equation*}
    \p \left((1 - \epss) \nnorm{v}_2^2 \leq \frac{p}{N} \norm{\pre v}_2^2 \leq (1 + \epss) \nnorm{v}_2^2 \right) \leq 2 \exp(-N  (\epss^2/4 - \epss^3/6) \})
  \end{equation*}

\label{lem:concentration_width}\emph{(\textbf{Concentration of Gaussian processes \cite{Boucheron2013}})}
Let $K$ be a closed subset of the unit sphere in ${\mathbb R}^m$ with Gaussian width $w(K)$, and let $g \sim N(0, I_m)$. Then for all $t > 0$
 \begin{equation*}
 \p \left(\sup_{x \in K} |\scp{g}{x}| \geq w(K) + t \right) \leq \exp(-t^2/2). 
\end{equation*}

\label{lem:extremesingularvalues}\hspace*{-.7ex}\emph{(\textbf{Concentration of extreme singular values of Gaussian matrices \cite{Vershynin2010}})}\\
  Let $X$ be an $n \times d$ Gaussian matrix with i.i.d.~$N(0,1)$-entries. Denote by $\sigma_{\min}(X)$
  and $\sigma_{\max}(X)$ the minimum respectively maximum singular value of $X$. Then for any $t > 0$
\begin{equation*}
\p(\sigma_{\min}(X) \geq \sqrt{n} - \sqrt{d} - t) \leq \exp(-t^2 / 2), \qquad \p(\sigma_{\max}(X) \geq \sqrt{n} + \sqrt{d} + t) \leq \exp(-t^2 / 2).  
\end{equation*}

\label{lem:hansonwright}\emph{(\textbf{Concentration of quadratic forms \cite{Hsu2012}})}\\
Let $A$ be a an $m \times n$ matrix, $\Gamma = A^{\T} A$, and $g \sim N(0, I_n)$. Then for all $t > 0$
\begin{equation*}
  \p(\nnorm{A g}_2^2  > \tr(\Gamma) + 2 \sqrt{\tr(\Gamma^2) t} + 2 \nnorm{\Gamma}_2 t) \leq \exp(-t). 
\end{equation*}

proposition.raw:
\label{prop:negative_result} Let $\beta^* = 0$ and $\Pi^* = I_n$, i.e., $\mathbf{y} = \eps$ and consider the estimator \eqref{eq:lsq} with $k = n$. Then there exist constants $c,C > 0$ such that with probability at least $1 - C \exp(-c n)$
\begin{equation*}
\nnorm{\wh{\beta}}_2^2 \geq \frac{n}{2n + d}\frac{\sigma^2}{32\pi^2}.
\end{equation*}

corollary.raw:
\label{corro:refitting} For any $\delta \in (0,1)$, under the conditions of Theorem \ref{theo:constrained_permutation}, if it additionally holds that 
\begin{equation*}
\text{\emph{SNR}} > \frac{2 (1 + \sqrt{2})^2 \epss^{-4}}{\delta^2}\,\cdot \frac{k^2  \{w(\mc{T}) \vee \log n\}^2}{n}, \qquad n-k \geq 9 \vee 4d, 
\end{equation*}
the following events hold with probability at least $1 - \delta - 2\exp(-\frac{1}{2} (d \vee \log n))$:
\begin{align*}
\wh{S} \coloneq \{i:\;\wh{\Pi}_{ii} \neq 1 \} = S^*, \quad\qquad \nnorm{\wh{\wh{\beta}} - \beta^*}_2 \leq 
\frac{\sigma}{1 - \sqrt{\frac{4 d \vee \log n}{n - k}}} \sqrt{\frac{5 (d \vee \log n)}{n-k}}. 
\end{align*}
where $\wh{\wh{\beta}}$ denotes the ordinary least squares estimator based on data $\{(y_i, \mathbf{x}_i): \; i
\in [n] \setminus \wh{S} \}$.

proof.raw:
In view of Lemma \ref{lem:decoupling}, by definition of $\wh{\Pi}^{\T}$ and the fact that $\Pi^{*\T}$ is a feasible solution, we have
 \begin{align*} 
&\nnorm{\pr_X^{\perp}\wh{\Pi}^{\T} \y}_2^2  \leq  \nnorm{\pr_X^{\perp}\Pi^{*\T} \y}_2^2 \\
  \Rightarrow \quad & \nnorm{\pr_X^{\perp}(\wh{\Pi}^{\T}  - \Pi^{*\T}) \y + \pr_X^{\perp}\Pi^{*\T} \y }_2^2 \leq \nnorm{\pr_X^{\perp}\Pi^{*\T} \y}_2^2 \\
  \Rightarrow \quad  & \nnorm{\pr_X^{\perp}(\wh{\Pi}^{\T}  - \Pi^{*\T}) \y}_2^2 \leq 2 |\nscp{\pr_X^{\perp}\Pi^{*\T} \y}{(\wh{\Pi}^{\T}  - \Pi^{*\T}) \y}|. 
 \end{align*}
Since
\begin{equation*}
\pr_X^{\perp} \Pi^{*\T} \y = \pr_X^{\perp} (X \beta^* + \eps) = \pr_X^{\perp}\eps,
\end{equation*}
we have the implication that
\begin{equation*}
  \nnorm{\pr_X^{\perp}(\wh{\Pi}^{\T}  - \Pi^{*\T}) \y}_2^2 \leq 2 |\nscp{\pr_X^{\perp}\eps}{(\wh{\Pi}^{\T}  - \Pi^{*\T}) \y}|.
\end{equation*}
Dividing both sides by $\nnorm{\pr_X^{\perp}(\wh{\Pi}^{\T}  - \Pi^{*\T}) \y}_2$, we obtain that
\begin{align}
  &\nnorm{(\wh{\Pi}^{\T}  - \Pi^{*\T}) \y}_2^2 \nnorm{\pr_X^{\perp} \wh{\Delta}}_2^2 \leq 2 |\nscp{\pr_X^{\perp}\eps}{\wh{\Delta}}| \nnorm{(\wh{\Pi}^{\T}  - \Pi^{*\T}) \y}_2, \qquad \wh{\Delta} \coloneq
  \frac{(\wh{\Pi}^{\T}  - \Pi^{*\T}) \y}{\nnorm{(\wh{\Pi}^{\T}  - \Pi^{*\T}) \y}_2} \notag \\
\Rightarrow \quad &\nnorm{(\wh{\Pi}^{\T}  - \Pi^{*\T}) \y}_2  \nnorm{\pr_X^{\perp}\wh{\Delta}}_2^2  \leq 2 |\nscp{\pr_X^{\perp}\eps}{\wh{\Delta}}| \label{eq:Pi_apply_Gordon}.  
\end{align}
\emph{i) Lower bounding the left hand side of \eqref{eq:Pi_apply_Gordon}.}\\
Observe that $\wh{\Delta} \in \mc{T}$ as defined in \eqref{eq:setT}. Moreover, note that under (\text{\textbf{G}}), the random subspace
$\text{range}(X) \subseteq {\mathbb R}^n$ follows the uniform distribution on the Grassmannian $\textsf{G}(n,d)$. Hence, applying Lemma \ref{lem:escape} with $K = \mc{T}$,
$V = \text{range}(X)$ and thus $m = n$ and $l = n-d$, we have for any $\epss \in (0,1/2)$ in compliance with \eqref{eq:cond_samples_unrelaxed}    
\begin{align}\label{eq:lowerbound}
  \begin{split}
   \p(\text{dist}(\mc{T}, \text{range}(X)) > \epss)
   &= \p \left(\min_{\Delta \in \mc{T}} \nnorm{\pr_X^{\perp} \Delta}_2 > \epss \right) \\
   &\geq 1 - \frac{7}{2} \exp \left(-\frac{1}{2} \left( \frac{(1 - \epss)\nu_{n-d} - \epss \nu_n  - w(\mc{T})}{3 + \epss + \epss \nu_n / \nu_{n-d}} \right)^2 \right) \\
   &\geq 1 - \frac{7}{2} \exp \left(-\frac{\psi(\epss, d/n) \nu_n^2}{8} \right), \quad
   \psi(\epss, d/n) \coloneq \left( \frac{(1- \epss) \frac{\nu_{n-d}}{\nu_n} - \epss}{3 + \epss + \frac{\epss^2}{1-\epss}} \right)^2,
 \end{split}
\end{align}
where the last inequality follows from condition \eqref{eq:cond_samples_unrelaxed}. Conditional on the event $\{ \nnorm{\pr_X^{\perp} \Delta}_2 \geq \epss \}$, which holds with the probability as stated, the left hand side of \eqref{eq:Pi_apply_Gordon} is lower bounded by $\epss^2 \nnorm{(\wh{\Pi}^{\T}  - \Pi^{*\T}) \y}_2$.  
\vskip1ex
\noindent \emph{ii) Upper bounding the right hand side of \eqref{eq:Pi_apply_Gordon}.}\\
Consider $t > 0$ arbitrary, to be chosen later.  We have
\begin{align*}
\p(|\nscp{\pr_X^{\perp}\eps}{\wh{\Delta}}| \geq t) \leq \p \left(\sup_{\Delta \in \mc{T}} |\nscp{\pr_X^{\perp}\eps}{\Delta}| > t \right). 
\end{align*}
\noindent Now note that $\eps$ and $\pr_X^{\perp}$ are independent. As a result, when conditioning on $\pr_X^{\perp}$, we have from Lemma \ref{lem:concentration_width}
that
\begin{align*}
  \p \left(\sup_{\Delta \in \mc{T}} |\nscp{\pr_X^{\perp}\eps}{\Delta}| > t \;\;\Big| \pr_X^{\perp} \right) &\leq
  \p \left(\sup_{\Delta \in \mc{T}} |\nscp{\pr_X^{\perp}\eps}{\Delta}| > \E\left[\sup_{\Delta \in \mc{T}}  |\nscp{\pr_X^{\perp}\eps}{\Delta}| \;\; \Big|  \pr_X^{\perp} \right] +  \tau \;\;\Big| \pr_X^{\perp} \right) \\
                                                                                                           &\leq \p \left(\sup_{\Delta \in \mc{T}} |\nscp{\pr_X^{\perp}\eps}{\Delta}| > \sigma  w(\mc{T})  +  \tau \;\;\Big| \pr_X^{\perp} \right) \\
                                                                                                           &\leq \exp(-\tau^2 / (2 \sigma^2)),
                                                                                                             \quad \tau \coloneq t - \E\left[\sup_{\Delta \in \mc{T}}  |\nscp{\pr_X^{\perp}\eps}{\Delta}| \;\; \Big|  \pr_X^{\perp} \right] \\
&\qquad \qquad \qquad \qquad \qquad \;\; \geq  t - \sigma w(\mc{T}). 
\end{align*}
The second equality is a consequence of the Sudakov-Fernique comparison inequality (Theorem 2.2.3 in \cite{AdlerTaylor2007}) and the fact that
$\nnorm{\pr_X^{\perp}}_2 \leq 1$. Choosing $t = (1 + \sqrt{2}) \sigma \{w(\mc{T}) \vee \log n \}$, combining this result with i), and putting together the pieces in \eqref{eq:Pi_apply_Gordon}, the assertion of the lemma follows.

We first decompose
\begin{equation*}
  \pr_X^{\perp} \y = \pr_X^{\perp} (X \beta^* + \sqrt{n} e^* + \eps) = \pr_X^{\perp} \sqrt{n} e^*  + \wt{\eps}, \quad
  \wt{\eps} \coloneq \pr_X^{\perp} \eps.  
\end{equation*}
According to Lemma \ref{lem:decoupling_LAD}, since $\wt{e}$ is a minimizer, we have that
\begin{equation*}
  \frac{1}{n} \nnorm{\pr_X^{\perp} \sqrt{n}   (e^* - \wt{e}) + \wt{\eps}}_2^2 + \lambda \nnorm{\wt{e}}_1 \leq
  \frac{1}{n} \nnorm{\wt{\eps}}_2^2  + \lambda \nnorm{e^*}_1. 
\end{equation*}
Expanding the square on the left-hand side and re-arranging terms, we obtain that
\begin{equation}\label{eq:lasso_basic}
\frac{1}{n} \nnorm{\pr_X^{\perp} \sqrt{n}   (e^* - \wt{e})}_2^2 + \lambda \nnorm{\wt{e}}_1 \leq 2 |\scp{e^* - \wt{e}}{\wt{\eps}/\sqrt{n}}| + \lambda \nnorm{e^*}_1, 
\end{equation}
which implies
\begin{equation*}
 \lambda \nnorm{\wt{e}}_1 \leq 2 \nnorm{e^* - \wt{e}}_{1} \nnorm{\wt{\eps}/\sqrt{n}}_{\infty} + \lambda \nnorm{e^*}_1,
\end{equation*}
and in turn
\begin{align*}
  \lambda \nnorm{\wt{e}_{(S^*)^c} - e_{(S^*)^c}^*}_1 = \lambda \nnorm{\wt{e}_{(S^*)^c}}_1 &\leq 2 \nnorm{e^* - \wt{e}}_{1} \nnorm{\wt{\eps}/\sqrt{n}}_{\infty} + \lambda (\nnorm{e^*}_1 - \nnorm{\wt{e}_{S^*}}_1) \\
  &\leq  2 \nnorm{e^* - \wt{e}}_{1} \underbrace{\nnorm{\wt{\eps}/\sqrt{n}}_{\infty}}_{\invcoloneq \lambda_0} + \lambda \nnorm{e_{S^*}^*- \wt{e}_{S^*}}_1. 
\end{align*}
Re-arranging, we arrive at 
\begin{equation*}
(\lambda - 2\lambda_0) \nnorm{\wt{e}_{(S^*)^c} - e_{(S^*)^c}^*}_1 \leq (\lambda + 2 \lambda_0) \nnorm{e_{S^*}^*- \wt{e}_{S^*}}_1. 
\end{equation*}
Conditional on the event $\Lambda =\{\lambda \geq 4 \lambda_0 \}$, we hence have that
\begin{equation}\label{eq:cone_condition}
  \nnorm{\wt{e}_{(S^*)^c} - e_{(S^*)^c}^*}_1 \leq 3 \nnorm{\wt{e}_{S^*} - e_{S^*}^*}_1.
\end{equation}
\noindent Equipped with this is intermediate result, we go back to \eqref{eq:lasso_basic}. We first
obtain by re-arranging that 
\begin{align*}
  \frac{1}{n} \nnorm{\pr_X^{\perp} \sqrt{n}   (e^* - \wt{e})}_2^2 &\leq (2 \lambda_0 + \lambda) \nnorm{\wt{e} - e^*}_1 \\
  &\leq (2 \lambda_0 + \lambda) 4 \nnorm{\wt{e}_{S^*} - e_{S^*}^*}_1 \\
  &\leq (2 \lambda_0 + \lambda) 4 \sqrt{k} \nnorm{\wt{e}_{S^*} - e_{S^*}^*}_2, 
\end{align*}
where we have used \eqref{eq:cone_condition} in the second inequality.  
In order to lower bound the left hand side, note that \eqref{eq:cone_condition} can be written as
$\wt{e} - e^* \in \mc{C}(S^*, 3)$ according to \eqref{eq:lassocone}. Conditional on the event in Lemma
\ref{lem:RE},
\begin{equation*}
\frac{1}{n} \nnorm{\pr_X^{\perp} \sqrt{n}   (e^* - \wt{e})}_2^2 \geq  \epss \frac{n-d}{n}  \nnorm{e^* - \wt{e}}_2^2.
\end{equation*}
Combining this with the previous display, we find that
\begin{equation*}
 \nnorm{e^* - \wt{e}}_2 \leq 12  \epss^{-1} \frac{n}{n-d} \lambda \sqrt{k}. 
\end{equation*}
\noindent In view of Lemma \ref{lem:maximalgaussian}, the choice $\lambda = 4 (1 + M) \sigma \sqrt{2 \log(n) / n}$ for $M \geq 0$
guarantees that the event $\Lambda$ defined above \eqref{eq:cone_condition} occurs with probability at least $1 - 2n^{-M^2}$.
This completes the proof of the Lemma.

It is clear that $\mathcal{A}_{\gamma}\subseteq\bigcup_{i<j}\left\{(\x_i^\top\beta^*-\x_j^\top\beta^*)^2\le \gamma^2 \right\}$. Using the fact that $\x_i^\top\beta^*-\x_j^\top\beta^*\sim N(0,2\|\beta^*\|_2^2)$, we have
\begin{align*}
	\p\left(\mathcal{A}_{\gamma}\right)&\le\p\left(\bigcup_{i<j}\left\{-\dfrac{\gamma}{\sqrt{2}\|\beta^*\|_2}\le (\x_i -\x_j)^\top\dfrac{\beta^*}{\sqrt{2}\|\beta^*\|_2}\le \dfrac{\gamma}{\sqrt{2}\|\beta^*\|_2}\right\}\right)	\\
	&\le \sum_{i<j}\p\left( -\dfrac{\gamma}{\sqrt{2}\|\beta^*\|_2} \le g \leq \dfrac{\gamma}{\sqrt{2}\|\beta^*\|_2} \right), \quad g \sim N(0,1)\\
	&\le\dfrac{n(n-1)}{2} \dfrac{\gamma}{\|\beta^*\|_2\sqrt{\pi}} \quad \text{by Lemma \ref{lem:smallball} in Appendix \ref{app:aux}.}
\end{align*}
Thus, it suffices to require that $\dfrac{n(n-1)}{2} \dfrac{\gamma}{\|\beta^*\|_2\sqrt{\pi}}<\delta$. Resolving for $\nnorm{\beta^*}_2$, this condition becomes
\[
\|\beta^*\|_2^2>\dfrac{n^2(n-1)^2}{4\delta^2\pi}\gamma^2.
\]

Without loss of generality, we may assume that $\Pi^* = I_n$. By construction of $\widehat{\Pi}(\beta^*)$, it is clear
