Since
\begin{equation*}
\pr_X^{\perp} \Pi^{*\T} \y = \pr_X^{\perp} (X \beta^* + \eps) = \pr_X^{\perp}\eps,
\end{equation*}
we have the implication that
\begin{equation*}
  \nnorm{\pr_X^{\perp}(\wh{\Pi}^{\T}  - \Pi^{*\T}) \y}_2^2 \leq 2 |\nscp{\pr_X^{\perp}\eps}{(\wh{\Pi}^{\T}  - \Pi^{*\T}) \y}|.
\end{equation*}
Dividing both sides by $\nnorm{\pr_X^{\perp}(\wh{\Pi}^{\T}  - \Pi^{*\T}) \y}_2$, we obtain that
\begin{align}
  &\nnorm{(\wh{\Pi}^{\T}  - \Pi^{*\T}) \y}_2^2 \nnorm{\pr_X^{\perp} \wh{\Delta}}_2^2 \leq 2 |\nscp{\pr_X^{\perp}\eps}{\wh{\Delta}}| \nnorm{(\wh{\Pi}^{\T}  - \Pi^{*\T}) \y}_2, \qquad \wh{\Delta} \coloneq
  \frac{(\wh{\Pi}^{\T}  - \Pi^{*\T}) \y}{\nnorm{(\wh{\Pi}^{\T}  - \Pi^{*\T}) \y}_2} \notag \\
\Rightarrow \quad &\nnorm{(\wh{\Pi}^{\T}  - \Pi^{*\T}) \y}_2  \nnorm{\pr_X^{\perp}\wh{\Delta}}_2^2  \leq 2 |\nscp{\pr_X^{\perp}\eps}{\wh{\Delta}}| \label{eq:Pi_apply_Gordon}.  
\end{align}
\emph{i) Lower bounding the left hand side of \eqref{eq:Pi_apply_Gordon}.}\\
Observe that $\wh{\Delta} \in \mc{T}$ as defined in \eqref{eq:setT}. Moreover, note that under (\text{\textbf{G}}), the random subspace
$\text{range}(X) \subseteq {\mathbb R}^n$ follows the uniform distribution on the Grassmannian $\textsf{G}(n,d)$. Hence, applying Lemma \ref{lem:escape} with $K = \mc{T}$,
$V = \text{range}(X)$ and thus $m = n$ and $l = n-d$, we have for any $\epss \in (0,1/2)$ in compliance with \eqref{eq:cond_samples_unrelaxed}    
\begin{align}\label{eq:lowerbound}
  \begin{split}
   \p(\text{dist}(\mc{T}, \text{range}(X)) > \epss)
   &= \p \left(\min_{\Delta \in \mc{T}} \nnorm{\pr_X^{\perp} \Delta}_2 > \epss \right) \\
   &\geq 1 - \frac{7}{2} \exp \left(-\frac{1}{2} \left( \frac{(1 - \epss)\nu_{n-d} - \epss \nu_n  - w(\mc{T})}{3 + \epss + \epss \nu_n / \nu_{n-d}} \right)^2 \right) \\
   &\geq 1 - \frac{7}{2} \exp \left(-\frac{\psi(\epss, d/n) \nu_n^2}{8} \right), \quad
   \psi(\epss, d/n) \coloneq \left( \frac{(1- \epss) \frac{\nu_{n-d}}{\nu_n} - \epss}{3 + \epss + \frac{\epss^2}{1-\epss}} \right)^2,
 \end{split}
\end{align}
where the last inequality follows from condition \eqref{eq:cond_samples_unrelaxed}. Conditional on the event $\{ \nnorm{\pr_X^{\perp} \Delta}_2 \geq \epss \}$, which holds with the probability as stated, the left hand side of \eqref{eq:Pi_apply_Gordon} is lower bounded by $\epss^2 \nnorm{(\wh{\Pi}^{\T}  - \Pi^{*\T}) \y}_2$.  
\vskip1ex
\noindent \emph{ii) Upper bounding the right hand side of \eqref{eq:Pi_apply_Gordon}.}\\
Consider $t > 0$ arbitrary, to be chosen later.  We have
\begin{align*}
\p(|\nscp{\pr_X^{\perp}\eps}{\wh{\Delta}}| \geq t) \leq \p \left(\sup_{\Delta \in \mc{T}} |\nscp{\pr_X^{\perp}\eps}{\Delta}| > t \right). 
\end{align*}
\noindent Now note that $\eps$ and $\pr_X^{\perp}$ are independent. As a result, when conditioning on $\pr_X^{\perp}$, we have from Lemma \ref{lem:concentration_width}
that
\begin{align*}
  \p \left(\sup_{\Delta \in \mc{T}} |\nscp{\pr_X^{\perp}\eps}{\Delta}| > t \;\;\Big| \pr_X^{\perp} \right) &\leq
  \p \left(\sup_{\Delta \in \mc{T}} |\nscp{\pr_X^{\perp}\eps}{\Delta}| > \E\left[\sup_{\Delta \in \mc{T}}  |\nscp{\pr_X^{\perp}\eps}{\Delta}| \;\; \Big|  \pr_X^{\perp} \right] +  \tau \;\;\Big| \pr_X^{\perp} \right) \\
                                                                                                           &\leq \p \left(\sup_{\Delta \in \mc{T}} |\nscp{\pr_X^{\perp}\eps}{\Delta}| > \sigma  w(\mc{T})  +  \tau \;\;\Big| \pr_X^{\perp} \right) \\
                                                                                                           &\leq \exp(-\tau^2 / (2 \sigma^2)),
                                                                                                             \quad \tau \coloneq t - \E\left[\sup_{\Delta \in \mc{T}}  |\nscp{\pr_X^{\perp}\eps}{\Delta}| \;\; \Big|  \pr_X^{\perp} \right] \\
&\qquad \qquad \qquad \qquad \qquad \;\; \geq  t - \sigma w(\mc{T}). 
\end{align*}
The second equality is a consequence of the Sudakov-Fernique comparison inequality (Theorem 2.2.3 in \cite{AdlerTaylor2007}) and the fact that
$\nnorm{\pr_X^{\perp}}_2 \leq 1$. Choosing $t = (1 + \sqrt{2}) \sigma \{w(\mc{T}) \vee \log n \}$, combining this result with i), and putting together the pieces in \eqref{eq:Pi_apply_Gordon}, the assertion of the lemma follows.   
\end{proof}
\noindent In order to complete the proof of Theorem \ref{theo:constrained_permutation}, we need one last lemma whose proof is deferred to Appendix \ref{app:Xteps}.

\begin{lemma}\label{lem:Xteps} Let $\sigma_{\min}(\cdot)$ denote the minimum singular value of a matrix. If $n \geq 9 \vee 4d$, it holds that
\begin{align*}
  &\p \left( \left \{\sigma_{\min}(X / \sqrt{n}) < 1 - \sqrt{\frac{4 d \vee \log n}{n}} \right \}   \cup \left\{ \norm{ \left(\frac{X^{\T} X}{n} \right)^{-1} \frac{X^{\T} \eps}{\sqrt{n}}}_2 \geq \sigma \frac{\sqrt{5 (d \vee \log n)} \}}{1 - \sqrt{\frac{4 d \vee \log n}{n}}} \right \} \right)\\
  &\leq 2 \exp \left(-\frac{1}{2} (d \vee \log n) \right).  
\end{align*}
\end{lemma}
\noindent Equipped with Lemmas \ref{lem:bound_pi} and \ref{lem:Xteps}, we are in position to conclude
Theorem \ref{theo:constrained_permutation}. Expanding the expression for $\wh{\beta}$ in \eqref{eq:decomposition}, we obtain that
\begin{align*}
  \wh{\beta} = \left(\frac{X^{\T} X}{n} \right)^{-1} \frac{X^{\T} \wh{\Pi}^{\T} \y}{n} 
  &= \left(\frac{X^{\T} X}{n} \right)^{-1} \frac{X^{\T} \Pi^{*\T} \y}{n} + \left(\frac{X^{\T} X}{n} \right)^{-1} \frac{X^{\T} (\wh{\Pi}^{\T}  - \Pi^{*\T}) \y}{n} \\
  &= \beta^* + \left( \frac{X^{\T} X}{n} \right)^{-1} \frac{X^{\T} (\eps + (\wh{\Pi}^{\T} - \Pi^{*\T}) \y)}{n},  
\end{align*}
and thus
\begin{align*}
  \nnorm{\wh{\beta} - \beta^*}_2 &\leq  \frac{\norm{ \left(\frac{X^{\T} X}{n} \right)^{-1} \frac{X^{\T} \eps}{\sqrt{n}}}_2}{\sqrt{n}} + \frac{\norm{\left(\frac{X^{\T} X}{n} \right)^{-1} \frac{X^{\T}}{\sqrt{n}}}_2 \nnorm{(\wh{\Pi}^{\T} - \Pi^{*\T}) \y}_2}{\sqrt{n}} \\
                                 &\leq \frac{\norm{ \left(\frac{X^{\T} X}{n} \right)^{-1} \frac{X^{\T} \eps}{\sqrt{n}}}_2}{\sqrt{n}} + \frac{\frac{1}{\sigma_{\min}(X / \sqrt{n})}\nnorm{(\wh{\Pi}^{\T} - \Pi^{*\T}) \y}_2}{\sqrt{n}} \\
&\leq \frac{\sigma}{1 - \sqrt{\frac{4 d \vee \log n}{n}}} \left(\sqrt{\frac{5 (d \vee \log n)}{n}} + \frac{2 (1 + \sqrt{2})\sigma \epss^{-2} \{w(\mc{T}) \vee \log n\}}{\sqrt{n}} \right)                                   
\end{align*}
with the stated probability by combining Lemmas \ref{lem:bound_pi} and \ref{lem:Xteps}.

}

Observe that the event $\{\wh{S} = S^* \}$ is implied by the event
\begin{equation*}
\left\{ \min_{i \in S^*} |y_i - y_{\varphi^{-1}(i)}| > \nnorm{\Pi^{*\T} \y - \wh{\Pi}^{\T} \y}_{\infty} \right \},  
\end{equation*}
which is in turn implied by
\begin{equation*}
\left\{ \min_{i \in S^*} |y_i - y_{\varphi^{-1}(i)}| > \nnorm{\Pi^{*\T} \y - \wh{\Pi}^{\T} \y}_{2} \invcoloneq \gamma \right\},  
\end{equation*} 
We now have 
\begin{align*}
\p\left(\min_{i \in S^*} |y_i - y_{\varphi^{-1}(i)}| \leq \gamma \right) 
&\leq \sum_{i \in S^*} \p\left(|y_i - y_{\varphi^{-1}(i)}| \leq \gamma \right) \\
&\leq k  \max_{i \neq j} \p\left(|y_i - y_{j}| \leq \gamma \right).
\end{align*}
Note that for any $i \neq j$, $y_i - y_j \sim N(0, 2 (\nnorm{\beta^*}_2^2 + \sigma^2))$. Invoking 
Lemma \ref{lem:smallball}, we thus obtain that for any $i \neq j$ 
\begin{equation*}  
\p\left(|y_i - y_{j}| \leq \gamma \right) \leq \frac{\gamma}{\sqrt{2 (\nnorm{\beta^*}_2^2 + \sigma^2)}}.
\end{equation*}
It hence follows from the previous two displays that for any $\delta > 0$, 
\begin{equation*}
\p\left(\min_{i \in S^*} |y_i - y_{\varphi^{-1}(i)}| \leq \gamma \right) \leq \delta
\end{equation*}
if 
\begin{equation*}
\nnorm{\beta^*}_2^2 > \frac{k^2 \gamma^2}{2 \delta^2}. 
\end{equation*}
Substituting $\gamma$ by the bound from Lemma \ref{lem:bound_pi}, the above condition becomes
\begin{equation*}
\text{SNR} > \frac{2 (1 + \sqrt{2})^2 \epss^{-4}}{\delta^2}\,\cdot \frac{k^2  \{w(\mc{T}) \vee \log n\}^2}{n },
\end{equation*}    
and the first part of the corollary follows from Lemma \ref{lem:bound_pi}. Turning to the second part, consider
the least squares estimator using the reduced data set $\{(\x_i, y_i), \; i \in [n] \setminus S^* \}$ and denote
by $\wh{\beta}(S^*)$ the corresponding least squares estimator. We then have for any $\delta > 0$ 
\begin{equation*}
\p(\nnorm{\wh{\beta}(S^*) - \beta^*}_2 \leq \delta) = \p(\nnorm{\wh{\beta}(S^*) - \beta^*}_2 \leq \delta, \wh{S} = S^*) + 
\p(\nnorm{\wh{\beta}(S^*) - \beta^*}_2 \leq \delta, \wh{S} \neq S^*),
\end{equation*} 
which implies 
\begin{equation*}
\p(\nnorm{\wh{\wh{\beta}} - \beta^*}_2 \leq \delta) \geq \p(\nnorm{\wh{\beta}(S^*) - \beta^*}_2 \leq \delta) - \p(\wh{S} \neq S^*). 
\end{equation*}
It thus remains to control the first probability on the left hand side, which can be done with arguments similar 
to those used in the last part of the proof of Theorem \ref{theo:constrained_permutation}.

