We start with a Lemma that parallels Lemma \ref{lem:decoupling}. The reasoning is analogous, and the proof is hence omitted.   
\begin{lemma}\label{lem:decoupling_LAD} 
Consider optimization problem \eqref{eq:relax_2} with solution $(\wt{\beta}, \wt{e})$. Then, if $n \geq d$, with probability one
\begin{align*}
  \wt{e} \in \argmin_{e} \frac{1}{n} \nnorm{\pre_X^{\perp} (\y - \sqrt{n}  e)}_2^2 + \lambda \nnorm{e}_1, \quad
  \wt{\beta} \in \Bigg\{ &\left(\frac{X^{\T} X}{n} \right)^{-1} \frac{X^{\T} (\y - \sqrt{n} \wt{e})}{n}, \\
  &\wt{e} \in \argmin_{e} \frac{1}{n} \nnorm{\pre_X^{\perp} (\y - \sqrt{n} e)}_2^2 + \lambda \nnorm{e}_1 \Big \}.
\end{align*}
\end{lemma}
\noindent For our analysis of the optimization problem of Lemma \ref{lem:decoupling_LAD}, we need the following
crucial lemma whose proof is provided in Appendix \ref{app:lem:RE}.  
\begin{lemma}\label{lem:RE} There exists constants $c_1, c_2, \epss > 0$ so that
  if $k \leq c_1 \frac{n-d}{\log(n/k)}$, the following event holds with probability at least $1 - 2 \exp(-c_2 (n-d) )$. 
\begin{equation*}
  \left\{ \frac{1}{n} \nnorm{\pre_X^{\perp} v}_2^2 \geq \epss \frac{n-d}{n} \nnorm{v}_2^2, \quad v \in \mc{C}(S^*, 3)
  \right \},
\end{equation*}
with $S^* = \{j:\;\Pi_{jj}^* \neq 1 \}$ and $\mc{C}(S^*, 3)$ defined in \eqref{eq:lassocone}. 
\end{lemma}
\noindent In correspondence with Lemma \ref{lem:bound_pi}, we first bound $\nnorm{\wt{e} - e^*}_2$,
where $e^* = (\Pi^* X \beta^* - X \beta^*)/\sqrt{n}$.
\begin{lemma}\label{lem:bound_e} Under the conditions of Theorem \ref{theo:relaxation}, with probability at least $1 - 2 \exp(-c_{\epss} (n-d))  - 2n^{-M^2}$, we have 
\begin{equation*}
\nnorm{\wt{e} - e^*}_2 \leq   48 (1 + M) \sigma  \frac{n}{n-d} \epss^{-1} \sqrt{\frac{k \log n}{n}}.  
\end{equation*}
\end{lemma}
\begin{proof} We first decompose
\begin{equation*}
  \pr_X^{\perp} \y = \pr_X^{\perp} (X \beta^* + \sqrt{n} e^* + \eps) = \pr_X^{\perp} \sqrt{n} e^*  + \wt{\eps}, \quad
  \wt{\eps} \coloneq \pr_X^{\perp} \eps.  
\end{equation*}
According to Lemma \ref{lem:decoupling_LAD}, since $\wt{e}$ is a minimizer, we have that
\begin{equation*}
  \frac{1}{n} \nnorm{\pr_X^{\perp} \sqrt{n}   (e^* - \wt{e}) + \wt{\eps}}_2^2 + \lambda \nnorm{\wt{e}}_1 \leq
  \frac{1}{n} \nnorm{\wt{\eps}}_2^2  + \lambda \nnorm{e^*}_1. 
\end{equation*}
Expanding the square on the left-hand side and re-arranging terms, we obtain that
\begin{equation}\label{eq:lasso_basic}
\frac{1}{n} \nnorm{\pr_X^{\perp} \sqrt{n}   (e^* - \wt{e})}_2^2 + \lambda \nnorm{\wt{e}}_1 \leq 2 |\scp{e^* - \wt{e}}{\wt{\eps}/\sqrt{n}}| + \lambda \nnorm{e^*}_1, 
\end{equation}
which implies
\begin{equation*}
 \lambda \nnorm{\wt{e}}_1 \leq 2 \nnorm{e^* - \wt{e}}_{1} \nnorm{\wt{\eps}/\sqrt{n}}_{\infty} + \lambda \nnorm{e^*}_1,
\end{equation*}
and in turn
\begin{align*}
  \lambda \nnorm{\wt{e}_{(S^*)^c} - e_{(S^*)^c}^*}_1 = \lambda \nnorm{\wt{e}_{(S^*)^c}}_1 &\leq 2 \nnorm{e^* - \wt{e}}_{1} \nnorm{\wt{\eps}/\sqrt{n}}_{\infty} + \lambda (\nnorm{e^*}_1 - \nnorm{\wt{e}_{S^*}}_1) \\
  &\leq  2 \nnorm{e^* - \wt{e}}_{1} \underbrace{\nnorm{\wt{\eps}/\sqrt{n}}_{\infty}}_{\invcoloneq \lambda_0} + \lambda \nnorm{e_{S^*}^*- \wt{e}_{S^*}}_1. 
\end{align*}
Re-arranging, we arrive at 
\begin{equation*}
(\lambda - 2\lambda_0) \nnorm{\wt{e}_{(S^*)^c} - e_{(S^*)^c}^*}_1 \leq (\lambda + 2 \lambda_0) \nnorm{e_{S^*}^*- \wt{e}_{S^*}}_1. 
\end{equation*}
Conditional on the event $\Lambda =\{\lambda \geq 4 \lambda_0 \}$, we hence have that
\begin{equation}\label{eq:cone_condition}
  \nnorm{\wt{e}_{(S^*)^c} - e_{(S^*)^c}^*}_1 \leq 3 \nnorm{\wt{e}_{S^*} - e_{S^*}^*}_1.
\end{equation}
\noindent Equipped with this is intermediate result, we go back to \eqref{eq:lasso_basic}. We first
obtain by re-arranging that 
\begin{align*}
  \frac{1}{n} \nnorm{\pr_X^{\perp} \sqrt{n}   (e^* - \wt{e})}_2^2 &\leq (2 \lambda_0 + \lambda) \nnorm{\wt{e} - e^*}_1 \\
  &\leq (2 \lambda_0 + \lambda) 4 \nnorm{\wt{e}_{S^*} - e_{S^*}^*}_1 \\
  &\leq (2 \lambda_0 + \lambda) 4 \sqrt{k} \nnorm{\wt{e}_{S^*} - e_{S^*}^*}_2, 
\end{align*}
where we have used \eqref{eq:cone_condition} in the second inequality.  
In order to lower bound the left hand side, note that \eqref{eq:cone_condition} can be written as
$\wt{e} - e^* \in \mc{C}(S^*, 3)$ according to \eqref{eq:lassocone}. Conditional on the event in Lemma
\ref{lem:RE},
\begin{equation*}
\frac{1}{n} \nnorm{\pr_X^{\perp} \sqrt{n}   (e^* - \wt{e})}_2^2 \geq  \epss \frac{n-d}{n}  \nnorm{e^* - \wt{e}}_2^2.
\end{equation*}
Combining this with the previous display, we find that
\begin{equation*}
 \nnorm{e^* - \wt{e}}_2 \leq 12  \epss^{-1} \frac{n}{n-d} \lambda \sqrt{k}. 
\end{equation*}
\noindent In view of Lemma \ref{lem:maximalgaussian}, the choice $\lambda = 4 (1 + M) \sigma \sqrt{2 \log(n) / n}$ for $M \geq 0$
guarantees that the event $\Lambda$ defined above \eqref{eq:cone_condition} occurs with probability at least $1 - 2n^{-M^2}$.
This completes the proof of the Lemma. 
\end{proof}
\noindent Using Lemmas \ref{lem:bound_pi} and \ref{lem:decoupling_LAD}, the proof of the theorem is completed along the lines
of the last part of the proof of Theorem \ref{theo:constrained_permutation}. For brevity, we omit those steps here.

