The proof of part (a) of the theorem relies on two lemmas, which are stated and proved first. 
\begin{lemma}\label{lem:up}
Let $\gamma, \delta > 0$. Consider the event 
\begin{equation}\label{eq:Agamma}
\mathcal{A}_{\gamma}= \left\{\min_{i<j}(\x_i^\top\beta^*-\x_j^\top\beta^*)^2\le \gamma^2 \right\}.
\end{equation}
Then $\p\left( \mathcal{A}_{\gamma}\right)< \delta$ if 
\[
\nnorm{\beta^*}_2^2>\dfrac{n^2(n-1)^2}{4\delta^2\pi}\gamma^2.
\]	
\end{lemma}

\begin{proof}
It is clear that $\mathcal{A}_{\gamma}\subseteq\bigcup_{i<j}\left\{(\x_i^\top\beta^*-\x_j^\top\beta^*)^2\le \gamma^2 \right\}$. Using the fact that $\x_i^\top\beta^*-\x_j^\top\beta^*\sim N(0,2\|\beta^*\|_2^2)$, we have
\begin{align*}
	\p\left(\mathcal{A}_{\gamma}\right)&\le\p\left(\bigcup_{i<j}\left\{-\dfrac{\gamma}{\sqrt{2}\|\beta^*\|_2}\le (\x_i -\x_j)^\top\dfrac{\beta^*}{\sqrt{2}\|\beta^*\|_2}\le \dfrac{\gamma}{\sqrt{2}\|\beta^*\|_2}\right\}\right)	\\
	&\le \sum_{i<j}\p\left( -\dfrac{\gamma}{\sqrt{2}\|\beta^*\|_2} \le g \leq \dfrac{\gamma}{\sqrt{2}\|\beta^*\|_2} \right), \quad g \sim N(0,1)\\
	&\le\dfrac{n(n-1)}{2} \dfrac{\gamma}{\|\beta^*\|_2\sqrt{\pi}} \quad \text{by Lemma \ref{lem:smallball} in Appendix \ref{app:aux}.}
\end{align*}
Thus, it suffices to require that $\dfrac{n(n-1)}{2} \dfrac{\gamma}{\|\beta^*\|_2\sqrt{\pi}}<\delta$. Resolving for $\nnorm{\beta^*}_2$, this condition becomes
\[
\|\beta^*\|_2^2>\dfrac{n^2(n-1)^2}{4\delta^2\pi}\gamma^2.
\]
\end{proof}
\noindent The following lemma is of interest in its own when the design matrix is fixed and both $\beta^*$ and $\sigma^2$ are known or accurate estimates of these quantities are available. Condition \eqref{eq:fix} can then be evaluated explicitly, at least after substituting $\beta^*$ and $\sigma^2$ by their respective estimates.  The result is close in spirit to those in the framework in \cite{Collier2016}.
\begin{lemma}\label{lem:fixed}
Conditional on $X$, we have $\p \left(\widehat{\Pi}(\beta^*) \ne \Pi^*\mid X \right)<\delta$ if
\begin{equation}\label{eq:fix}
\min_{i<j}\left(\x_i^\top\beta^*-\x_j^\top\beta^*\right)^2>4\sigma^2\log\dfrac{n(n-1)}{\delta}.
\end{equation}
\end{lemma}

\begin{proof} Without loss of generality, we may assume that $\Pi^* = I_n$. By construction of $\widehat{\Pi}(\beta^*)$, it is clear
  that $\widehat{\Pi}(\beta^*) \ne \Pi^*$ whenever there exists $i\ne j$ such that $(y_i-y_j)(\x_i^\top\beta^*-\x_j^\top\beta^*)<0$, that is, the order between $\x_i^\top\beta^*$ and $\x_j^\top\beta^*$ is different than that of $y_i, y_j$. First, conditioning on the random design matrix $X$,  we have
\begin{align*}
\p(\wh{\Pi}(\beta^*)\ne \Pi^* \mid X)&=2\p\left(\bigcup_{i<j}\left\{y_i-y_j>0 \mid \x_i^\top\beta^*-\x_j^\top\beta^*<0\right\}\right)\\\
&\le 2 \sum_{i<j}\p\left(y_i-y_j>0 \mid \x_i^\top\beta^*-\x_j^\top\beta^*<0\right)
\end{align*}
 Since $y_i-y_j\mid \x_i^\top\beta^*-\x_j^\top\beta^*\sim N(\x_i^\top\beta^*-\x_j^\top\beta^*, 2\sigma^2)$, using the usual tail bound for the Gaussian distribution for each term in the above sum, we obtain
 \begin{align*}
\p(\wh{\Pi}(\beta^*)\ne \Pi^* \mid X)&\le 2\sum_{i<j} \exp\left( -\dfrac{\left(\x_i^\top\beta^*-\x_j^\top\beta^*\right)^2}{4\sigma^2} \right)\\
&\le n(n-1)\exp\left( -\dfrac{\min_{i<j}\left(\x_i^\top\beta^*-\x_j^\top\beta^*\right)^2}{4\sigma^2} \right).
\end{align*}
Hence, for any $\delta>0$, $\p(\wh{\Pi}(\beta^*)\ne \Pi^* \mid X) <\delta$ if

\begin{equation*}
\min_{i<j}\left(\x_i^\top\beta^*-\x_j^\top\beta^*\right)^2>4\sigma^2\log\dfrac{n(n-1)}{\delta}.
\end{equation*}
\end{proof}

\noindent Combining Lemmas \ref{lem:up} and \ref{lem:fixed}, part (a) in Theorem \ref{theo:permutationrecovery} follows
immediately for $\wh{\Pi}(\beta^*)$ from the previous lemma by invoking Lemma \ref{lem:up} with $\gamma = 2 \sigma \sqrt{\log\frac{n(n-1)}{\delta}}$. We then have
$\p(\wh{\Pi}(\beta^*)\ne \Pi^*)\le \p(\mathcal{A}_{\gamma})+\left(1-\p(\mathcal{A}_{\gamma})\right)\delta<2\delta$ under the conditions of the theorem.
The general version of the theorem results from
\begin{align*}
  \min_{i < j} |\x_i^{\T} \wh{\theta} - \x_j^{\T} \wh{\theta}| &\geq  \min_{i < j} |\x_i^{\T} \beta^* - \x_j^{\T} \beta^*| - 2 \max_{1 \leq i \leq n} |\x_i^{\T} (\beta^* - \wh{\theta})| \\
  &\geq \min_{i < j} |\x_i^{\T} \beta^* - \x_j^{\T} \beta^*| - 2 \sigma \Delta. 
\end{align*}
conditional on the event $\{ \nnorm{X \beta^* - X \wh{\theta}}_{\infty} \leq \sigma \Delta \}$. The assertion follows from an application of
Lemma \ref{lem:up} with $\gamma = 2 \sigma \left(\sqrt{\log\frac{n(n-1)}{\delta}} + \Delta \right)$. 
\vskip2ex
\noindent The proof of part (b) in Theorem \ref{theo:permutationrecovery} requires another lemma.

\begin{lemma}\label{lem:low}
Consider the event $\mc{A}_{\gamma}$ in \eqref{eq:Agamma}. Then, for all $n \geq 5$, $\p\left( \mathcal{A}_{\gamma}\right)\ge 0.85$ if 
\begin{equation}\label{eq:lb}
\|\beta^*\|_2^2\le \dfrac{1}{25\pi}n^2\gamma^2.
\end{equation}
\end{lemma}
\begin{proof}
Since $\x_i^\top\beta^*/\|\beta^*\|_2 \sim N(0,1)$, we have for $g \sim N(0,1)$
\begin{equation}\label{eq:ap1}
p:=\p\left( -\dfrac{\gamma}{\sqrt{2}}<\x^\top\beta^*<\dfrac{\gamma}{\sqrt{2}}\right)=\p\left( -\dfrac{\gamma}{\sqrt{2}\nnorm{\beta^*}_2}<g<\dfrac{\gamma}{\sqrt{2}\nnorm{\beta^*}_2} \right)\ge \dfrac{\gamma}{\nnorm{\beta^*}_2\sqrt{2\pi}},
\end{equation}
whenever $\gamma < \frac{3}{\sqrt{2}} \nnorm{\beta^*}_2$, otherwise $p > .86$ as can be verified by evaluating the Gaussian cumulative distribution function numerically. 

\noindent Let  $\mathcal{B}:=\left\{-\dfrac{\gamma}{\sqrt{2}}<\x^\top\beta^*<\dfrac{\gamma}{\sqrt{2}}\right\}$. For \textit{i.i.d.} observations $\x_1,\ldots,\x_n$, let
\[
u:=\sum_{i=1}^n \mathbb{I}(\x_i\in \mathcal{B})\sim \text{binom}(n, p),
\]
with $p$ as defined in \eqref{eq:ap1}. The event $\mathcal{A}_{\gamma}$ in \eqref{eq:Agamma} occurs whenever at least two $\x_i, \x_j\in \mathcal{B}$, i.e., the event  $\left\{u\ge 2\right\}\subseteq\mathcal{A}_{\gamma}$. Let us suppose for the moment that $p \geq 3.5/n$ for $n\ge 5$.  Then
\begin{align*}
	\p\left(\mathcal{A}_{\gamma}\right)&\ge\p\left(u\ge 2\right)\\
&\geq 1-\left(1-\dfrac{3.5}{n}\right)^{n}-n\left(\dfrac{3.5}{n}\right)\left(1-\dfrac{3.5}{n}\right)^{n-1}\\
&>.85 \quad \text{for $n\ge 5$}.
\end{align*}
Using Eq.\eqref{eq:ap1}, we now conclude that $\p\left(\mathcal{A}_{\gamma}\right)\ge .85$ whenever $\dfrac{\gamma}{\|\beta^*\|_2 \sqrt{2\pi}}\ge 3.5/n$. This holds if 
\[
\|\beta^*\|_2^2 \le \dfrac{1}{25\pi}n^2 \gamma^2.
\]
\end{proof}









\noindent We finally turn to the proof of part (b) of the theorem. Define indices $i_0, j_0 \subset [n]$ by the relation $\x_{i_0}^\top\beta^*-\x_{j_0}^\top\beta^*=\min_{i<j}|\x_i^\top\beta^*-\x_j^\top\beta^*|$. For given $\gamma>0$, we have
\begin{align*}

\p(\widehat{\Pi}(\beta^*)\ne \Pi^*) &\ge \p\left(y_{i_0}-y_{j_0} <0\mid 0<\x_{i_0}^\top\beta^*-\x_{j_0}^\top\beta^*<\gamma\right)\p\left(0<\x_{i_0}^\top\beta^*-\x_{j_0}^\top\beta^*<\gamma\right)\\
                                    &= \p\left(\x_{i_0}^\top\beta^*+\sigma\epsilon_{i_0}-\x_{j_0}^\top\beta^*-\sigma\epsilon_{j_{0}} <0\mid 0<\x_{i_0}^\top\beta^*-\x_{j_0}^\top\beta^*<\gamma\right) \times \\
  &\quad \times \p\left(0<\x_{i_0}^\top\beta^*-\x_{j_0}^\top\beta^*<\gamma\right)\\
&\ge \p\left(\sigma\epsilon_{i_0}-\sigma\epsilon_{j_{0}} <-\gamma \right)\p\left(0<\x_{i_0}^\top\beta^*-\x_{j_0}^\top\beta^*<\gamma\right)\\
&\ge \p\left(g<-\dfrac{\gamma}{\sqrt{2}\sigma} \right)\p\left(0<\x_{i_0}^\top\beta^*-\x_{j_0}^\top\beta^*<\gamma\right)\\
                                    &\ge  \p\left(g<-\dfrac{4\sqrt{\pi}\nnorm{\beta^*}_2}{\sqrt{2}\sigma n}c \right)\p\left(0<\x_{i_0}^\top\beta^*-\x_{j_0}^\top\beta^*<\dfrac{4\sqrt{\pi}\nnorm{\beta^*}_2}{n}c\right), \\
  &\quad\;\; \text{by choosing $\gamma=\dfrac{4\sqrt{\pi}\nnorm{\beta^*}_2}{n}c$, for $0<c\le 1$.}\\
&\ge \Phi(-.1)(.85), \: \text{by Lemma \ref{lem:low}, for a choice of $c$ s.t.$\dfrac{4\sqrt{\pi}\nnorm{\beta^*}_2}{\sqrt{2}\sigma n}c\le .1$.}\\
&\ge.35,
\end{align*}
where in the penultimate line, $\Phi(x) = \int_{-\infty}^x \frac{1}{\sqrt{2\pi}}\exp(-t^2/2) \; dt$ denotes the Gaussian cumulative distribution function.  
Therefore, $\p(\wh{\Pi}(\beta^*)\ne\Pi^*)\ge .35$ whenever $\frac{\nnorm{\beta^*}_2^2}{\sigma^2}<\frac{C}{n^2}$ for some $C>0$. This concludes
the proof of part (b) of the theorem.

}\label{app:lem:RE}
The proof of Lemma \ref{lem:RE} is given at the end of this section. The proof depends on several
lemmas collected from the literature which are stated first.     
\vskip1ex
\noindent For $1 \leq s \leq p$, let $\mc{J}(s)$ denote the set of all index subsets of $[p]$ of
size $s$.    

\begin{defn} For  $J \in \mc{J}(s)$, and $\alpha \in [1,\infty)$, define 
\begin{equation}\label{eq:lassocone}
\mc{C}(J, \alpha) = \{v \in {\mathbb R}^p:\, \nnorm{v_{J^c}}_1 \leq \alpha \nnorm{v_J}_1 \}. 
\end{equation}
\end{defn}

\begin{defn}\cite{CandesTao2005} Let $A \in {\mathbb R}^{N \times p}$ and $B_0(s;p) = \{v \in {\mathbb R}^p: \; \nnorm{v}_0 \leq s \}$. Define the $s$-sparse minimum and maximum eigenvalues associated with $A$ by 
\begin{equation*}
  \lambda_{\min}(s) = \min_{v \in B_0(s;p) \setminus \{0\}} \frac{\nnorm{A v}_2^2}{\nnorm{v}_2^2}, \qquad
  \lambda_{\max}(s) = \max_{v \in B_0(s;p) \setminus \{0\}} \frac{\nnorm{A v}_2^2}{\nnorm{v}_2^2}. 
\end{equation*}
Let $\delta \in (0,1)$. We say that $A$ is an ($s$, $\delta$)-\textbf{restricted isometry}  if
\begin{equation*}
  1 - \delta \leq \lambda_{\min}(s) \leq \lambda_{\max}(s) \leq 1+\delta.
\end{equation*}
\end{defn}

\begin{defn}\cite{Bickel2009} Let $A \in {\mathbb R}^{N \times p}$. We define the $(s, \alpha)$-\textbf{restricted eigenvalue} by 
\begin{equation}\label{eq:recondition}
\phi(s, \alpha) = \min_{J \in \mc{J}(s)} \, \min_{v \in \mc{C}(J, \alpha) \setminus
  0}\, \, \frac{\nnorm{A v}_2^2}{\nnorm{v_J}_2^2}. 
\end{equation}   
\end{defn}



\begin{lemma}\cite{Bickel2009} Suppose that $A$ is a ($3s, \delta^*/4$)-restricted isometry for some $\delta^* \in (0,1)$. The $(s, 3)$-restricted eigenvalue then satisfies $\phi(s, 3) \geq 1 - \delta^*$. 
\end{lemma}

\begin{lemma}\cite{Baraniuk2006}
Let $A$ be a random of matrix of size $N \times p$ satisfying 
\begin{equation}\label{eq:normpreservation}
 \p((1 - \epss) \nnorm{v}_2^2 \leq \nnorm{A v}_2^2 \leq (1 + \epss) \nnorm{v}_2^2) \leq 2 \exp(-N c_0(\epss))
\end{equation}
for any $\epss \in (0,1)$ and any $v \in {\mathbb R}^p$, where $c_0(\epss) > 0$ is a constant depending only on $\epss$. Then for any $\delta \in (0,1)$, there exist constants $c_1, c_2 > 0$ depending only on $\delta$ such that $A$ is a $(q, \delta)$-restricted isometry for any $q \leq c_1 N / \log(p/q)$ with probability at least $1 - 2 \exp(-c_2 N)$. 
\end{lemma}

\begin{lemma}\label{lem:DasGupta}(from Lemma 2.2 in \cite{DasGupta2003})
  Let $\pre$ denote the orthogonal projection on an $N$-dimensional subspace of ${\mathbb R}^p$ chosen uniformly at
  random from the Grassmannian $\textsf{G}(p, N)$. Then, for any $v \in {\mathbb R}^p$ and any $\epss \in (0,1)$,
  \begin{equation*}
    \p \left((1 - \epss) \nnorm{v}_2^2 \leq \frac{p}{N} \norm{\pre v}_2^2 \leq (1 + \epss) \nnorm{v}_2^2 \right) \leq 2 \exp(-N  (\epss^2/4 - \epss^3/6) \})
  \end{equation*}
\end{lemma}

\noindent\emph{\textbf{Proof of Lemma \ref{lem:RE}}}: the lemma is essentially implied by the fact that under the stated conditions, the matrix $\pr_{X}^{\perp}$ has its $(k,3)$-restricted eigenvalue bounded away from zero by a constant $\epss$ as to be shown below. "Essentially" refers to the fact that it can be shown (cf.~\cite{Zhou2009}) that a matrix $A$ with restricted eigenvalue $\phi(k,3)$ obeys
\begin{equation*}
\nnorm{A v}_2^2 \geq \frac{1}{32} \phi(k,3) \nnorm{v}_2^2 \qquad \forall v \in \bigcup_{J \in \mc{J}(k)} \mc{C}(J,3). 
\end{equation*}  
As sketched above, a lower bound on $\phi(k,3)$ follows if $A$ is a $(3k, \delta^*/4)$ restricted isometry for some $\delta^* \in (0,1)$. That property is in turn satisfied with high probability if $A$ satisfies \eqref{eq:normpreservation}. Applying Lemma \ref{lem:DasGupta} with 
$\texttt{P} = \pr_{X}^{\perp}$, $p = n$ and $N = n-d$ yields the conclusion.

}\label{app:Xteps}
We invoke Lemma \ref{lem:hansonwright} conditional on $X$, with $\left(\frac{X^{\T} X}{n} \right)^{-1} \frac{X^{\T}}{\sqrt{n}}$ in the role of $A$, so that
$\Gamma = \frac{X}{\sqrt{n}} \left(\frac{X^{\T} X}{n} \right)^{-2} \frac{X^{\T}}{\sqrt{n}}$. Observe that 
\begin{align}\label{eq:traceineq}
\begin{split}
&(i)\;\;\tr(\Gamma) = \tr\left( \left(\frac{X^{\T} X}{n} \right)^{-1} \right) \leq  \frac{d}{\sigma^2_{\min}(X / \sqrt{n})}, \quad (ii) \;\; \nnorm{\Gamma}_2 = \frac{1}{\sigma^2_{\min}(X / \sqrt{n})}, \\
&(iii)\;\;\sqrt{\tr(\Gamma^2)} = \sqrt{\tr \left(\left(\frac{X^{\T} X}{n} \right)^{-2} \right)} \leq  \frac{\sqrt{d}}{\sigma^2_{\min}(X/\sqrt{n})}.
\end{split}
\end{align}
In view of the relations in \eqref{eq:traceineq}, application of Lemma \ref{lem:hansonwright} with $t = d \vee \log n$ and comparison of terms yields that
\begin{equation*}
  \p\left(\norm{ \left(\frac{X^{\T} X}{n} \right)^{-1} \frac{X^{\T} \eps}{\sqrt{n}}}_2 \; >  \sigma \frac{\sqrt{5 \{d \vee \log n \}}}{\sigma_{\min}(X / \sqrt{n})} \; \; \Bigg| X \right)
  \leq \exp(-d \vee \log n). 
\end{equation*}
Using Lemma \ref{lem:extremesingularvalues} for $\sigma_{\min}(X)$ with the choice $t = \sqrt{d \vee \log n}$, the assertion readily follows.

\noindent In other words, in a pure noise setting, $\nnorm{\wh{\beta}}_2$ will be bounded away from zero by a constant (assuming $d = O(n)$). A result of a similar flavor is shown in \cite{Abid2017}. For $d = 1$, they show that the estimator $\wh{\beta}$ converges almost surely to a limit different from $\beta^*$ as $n \rightarrow \infty$, and they derive an explicit expression for that limit. Our result here is more of a qualitative nature, but it is non-asymptotic and not limited to $d = 1$. 

Both the result in \cite{Abid2017} as well as Proposition \ref{prop:negative_result} raise the question whether there exist alternative estimators that do significantly better in a regime where $\Pi^*$ can be an \emph{arbitrary} element of $\mc{P}_n$. Theorem 1 in \cite{Pananjady2017} indicates that the answer is negative: they show that for any estimator $(\wt{\Pi}, \wt{\beta})$, one has       
\begin{equation*}
\sup_{\Pi^* \in \mc{P}_n, \; \beta^* \in {\mathbb R}^d} \E\left[\textstyle\frac{1}{n} \nnorm{\wt{\Pi} X \wt{\beta} - \Pi^* X  \beta^*}_2^2\right] \geq c \sigma^2. 
\end{equation*}
While the above lower bound concerns estimation of $\Pi^* X  \beta^*$ rather than $\beta^*$, accurate in-sample prediction (or synonymously denoising), i.e., recovery of $\Pi^* X  \beta^*$, is typically easier than recovery of $\beta^*$. Along this direction, another negative result is shown in \cite{Hsu2017}. They demonstrate that a lower bound on the signal-to-noise ratio (SNR)
\begin{equation}\label{eq:snr}
\text{SNR} = \nnorm{\beta^*}_2^2 / \sigma^2
\end{equation}
of the order $\Omega(d / \log \log n)$ is required for any estimator of $\beta^*$ to achieve a non-trivial expected relative estimation error\footnote{Non-trivial here refers to a relative estimation error of lower order than that of the estimator $\wh{\theta} \equiv 0$.}. As shown in \cite{Pananjady2016}, the condition $\text{SNR} > n^c$ for $c$ large enough is sufficient for the solution $\wh{\Pi}$ of \eqref{eq:lsq} to recover $\Pi^*$, in which case 
$\nnorm{\wh{\beta} - \beta^*}_2^2$ scales as $O(d/n)$ as in the usual regression setting in the absence of an unknown permutation.
